/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
d = np.load('source_pixels.npz')
rgb = d['rgb']
H,W = 144,256

def white_mask(f):
    return (f[:,:,0]>190)&(f[:,:,1]>190)&(f[:,:,2]>190)

def black_mask(f):
    # dark ball on green felt: all channels low, but exclude pockets/rails
    return (f[:,:,0]<60)&(f[:,:,1]<70)&(f[:,:,2]<60)

def centroid(m, min_area=3):
    ys,xs = np.nonzero(m)
    if len(xs)<min_area: return None, 0
    return (xs.mean(), ys.mean()), len(xs)

for i in range(0,96,3):
    f=rgb[i]
    wm=white_mask(f); bm=black_mask(f)
    wc,wa=centroid(wm); bc,ba=centroid(bm)
    print(i, 'white', wc, wa, 'black', bc, ba)
\""
